-- Требования к аналитикам данных в Казахстане.
-- Снимок на 2026-11-06. Источник: data/vacancies-2026-11-06.xlsx,
-- лист «Вакансии», строки 7–16. Сохранено карточек: 10.
-- В анализ включаем только selection_status = 'Да': сейчас это 8 вакансий.
-- Одна карточка исключена, ещё одна требует проверки.
-- Даты и требования сохранены как в исходной таблице; оговорки находятся в notes.
-- Отсутствующая зарплата хранится как NULL.
-- Повторный импорт пропускает существующие source_row.

BEGIN;

CREATE SCHEMA IF NOT EXISTS analyst_project;

CREATE TABLE IF NOT EXISTS analyst_project.vacancies (
    source_row INTEGER PRIMARY KEY,
    vacancy_id TEXT,
    title TEXT NOT NULL,
    company TEXT,
    city TEXT,
    experience_group TEXT,
    experience_card TEXT,
    experience_description TEXT,
    work_format TEXT,
    required_skills TEXT,
    preferred_skills TEXT,
    english TEXT,
    salary_from NUMERIC(14, 2) CHECK (salary_from >= 0),
    salary_to NUMERIC(14, 2) CHECK (salary_to >= 0),
    currency TEXT,
    tax_status TEXT,
    published_date DATE,
    checked_date DATE,
    page_status TEXT,
    source TEXT,
    source_url TEXT,
    notes TEXT,
    selection_status TEXT NOT NULL CHECK (selection_status IN ('Да', 'Нет', 'Проверить')),
    selection_reason TEXT,
    CHECK (salary_from IS NULL OR salary_to IS NULL OR salary_from <= salary_to)
);

COMMENT ON TABLE analyst_project.vacancies IS
    'Пилотная выборка вакансий Казахстана на 2026-11-06. Выводы ограничены собранными объявлениями.';
COMMENT ON COLUMN analyst_project.vacancies.source_row IS
    'Номер строки в исходном снимке Excel; ключ для повторного запуска импорта.';
COMMENT ON COLUMN analyst_project.vacancies.selection_status IS
    'Да — включить; Нет — исключить; Проверить — пока не включать.';

INSERT INTO analyst_project.vacancies (
