COMMIT;

-- Контроль состава выборки.
SELECT
    COUNT(*) AS total_cards,
    COUNT(*) FILTER (WHERE selection_status = 'Да') AS included,
    COUNT(*) FILTER (WHERE selection_status = 'Нет') AS excluded,
    COUNT(*) FILTER (WHERE selection_status = 'Проверить') AS needs_review
FROM analyst_project.vacancies;
